<?php
namespace Bookly\Lib\AiAdmin;

use Bookly\Lib;

/**
 * Knowledge of the setup assistant. The base itself — the rules, the indexes and the files the
 * model loads with get_knowledge(path) — is kept by Cloud and fixed there without a plugin
 * release; Cloud puts the rules into the prompt itself. The plugin keeps what it renders: the
 * translated labels of the proposal card (lib/ai_admin/labels, generated by
 * assets/ai-setup-kit/tools/build.py next to Rules.php).
 */
abstract class Knowledge
{
    /** Cloud agent the admin assistant runs as. */
    const AGENT = Lib\Entities\AiConversation::AGENT_ADMIN;

    /**
     * The assistant needs a Cloud account with the product AI Admin Assistant.
     *
     * @return bool
     */
    public static function available()
    {
        return get_option( 'bookly_cloud_token' ) != ''
            && Lib\Cloud\API::getInstance()->account->productActive( Lib\Cloud\Account::PRODUCT_AI_ADMIN );
    }

    /**
     * A file of the base by its path ("index/general.md", "cards/option.x.md"): the path Cloud
     * found and the options the file describes, not its text — the text never leaves Cloud, it
     * takes the place of the reference in the get_knowledge result there. Cloud forgives the
     * usual slips of the model (no folder, a goal without "goal."); when there is no such file,
     * the path is null and Cloud names the nearest paths. Files repeat within a conversation, so
     * they are kept for the request.
     *
     * @param string $path
     * @return array array( 'path' => string|null, 'options' => string[], 'suggestions' => string[] )
     */
    public static function find( $path )
    {
        static $files = array();
        $path = ltrim( trim( (string) $path ), '/' );
        if ( ! preg_match( '~^((index|cards|goals|actions)/)?[A-Za-z0-9_.\-]+$~', $path ) || strpos( $path, '..' ) !== false ) {
            return array( 'path' => null, 'options' => array(), 'suggestions' => array() );
        }
        if ( ! array_key_exists( $path, $files ) ) {
            /** @var Lib\Cloud\AiAdmin $ai */
            $ai             = Lib\Cloud\API::getInstance()->getProduct( Lib\Cloud\Account::PRODUCT_AI_ADMIN );
            $files[ $path ] = $ai->knowledgeFile( self::AGENT, $path );
        }

        return $files[ $path ];
    }

    /**
     * Translation of a label msgid for the admin's locale: the generated labels file first, then
     * the Bookly and WordPress text domains, then the msgid as is.
     *
     * @param string $msgid
     * @return string
     */
    public static function label( $msgid )
    {
        static $labels;
        if ( $labels === null ) {
            $labels = array();
            $file   = __DIR__ . '/labels/' . get_user_locale() . '.json';
            if ( is_file( $file ) ) {
                $data   = json_decode( (string) file_get_contents( $file ), true );
                $labels = is_array( $data ) ? $data : array();
            }
        }
        if ( isset( $labels[ $msgid ] ) ) {
            return $labels[ $msgid ];
        }
        $translated = __( $msgid, 'bookly' );
        if ( $translated === $msgid ) {
            $translated = translate( $msgid, 'default' );
        }

        return $translated;
    }
}
